const F={"/apple-touch-icon.png":["image/png","",0,"public, max-age=86400"],"/fonts/OFL.txt":["text/plain; charset=utf-8","",1,"public, max-age=86400"],"/fonts/atkinson-400.woff2":["font/woff2","",0,"public, max-age=86400"],"/fonts/atkinson-700.woff2":["font/woff2","",0,"public, max-age=86400"],"/icon-192.png":["image/png","",0,"public, max-age=86400"],"/icon-512.png":["image/png","",0,"public, max-age=86400"],"/":["text/html; charset=utf-8","",1,"no-cache"],"/manifest.webmanifest":["application/manifest+json","",1,"no-cache"],"/sw.js":["text/javascript; charset=utf-8","",1,"no-cache"]};
const bytes=b=>Uint8Array.from(atob(b),c=>c.charCodeAt(0));
export default{async fetch(req){
  const u=new URL(req.url); let p=u.pathname; if(p==='/index.html')p='/';
  const f=F[p]; if(!f)return new Response('Não encontrado',{status:404,headers:{'content-type':'text/plain; charset=utf-8'}});
  const [tipo,b64,gz,cache]=f; let corpo=new Blob([bytes(b64)]).stream();
  if(gz)corpo=corpo.pipeThrough(new DecompressionStream('gzip'));
  return new Response(corpo,{headers:{'content-type':tipo,'cache-control':cache,'x-content-type-options':'nosniff'}});
}};
